COLORREF Blend(COLORREF a, COLORREF b, float t) {
    return RGB((int)(GetRValue(a)*(1-t)+GetRValue(b)*t), (int)(GetGValue(a)*(1-t)+GetGValue(b)*t), (int)(GetBValue(a)*(1-t)+GetBValue(b)*t));
}
