COLORREF ContrastText(COLORREF c){int luminance=(GetRValue(c)*299+GetGValue(c)*587+GetBValue(c)*114)/1000;return luminance>150?RGB(10,24,32):RGB(240,250,250);}
void ApplyAppearance(int theme,int opacity,COLORREF accent){int nextTheme=std::clamp(theme,0,2);bool themeChanged=nextTheme!=g_activeTheme;g_activeTheme=nextTheme;const ThemePalette& p=g_themes[g_activeTheme];C_BG=p.bg;C_SIDEBAR=p.sidebar;C_PANEL=p.panel;C_PANEL_HI=p.panelHighlight;C_WHITE=p.text;C_MUTED=p.muted;C_CYAN=accent;C_CYAN_DARK=Blend(accent,RGB(7,20,28),0.48f);if(g_window){if(g_activeOpacity!=opacity){SetLayeredWindowAttributes(g_window,0,(BYTE)std::clamp((int)std::lround(opacity*2.55),0,255),LWA_ALPHA);g_activeOpacity=opacity;}if(themeChanged||!g_appearanceNativeInitialized){SetAcrylic(g_window);g_appearanceNativeInitialized=true;}}}
Color GColor(COLORREF c, BYTE alpha=255) { return Color(alpha,GetRValue(c),GetGValue(c),GetBValue(c)); }
RectF R(float x,float y,float w,float h) { return RectF(x,y,w,h); }
void FillRect(Graphics& g, RectF r, COLORREF c) { SolidBrush b(GColor(c)); g.FillRectangle(&b,r); }
void RoundRect(Graphics& g, RectF r, COLORREF c, float radius=16, COLORREF border=0, float borderWidth=0, BYTE alpha=255) {
    GraphicsPath p; float d=radius*2; p.AddArc(r.X,r.Y,d,d,180,90); p.AddArc(r.GetRight()-d,r.Y,d,d,270,90); p.AddArc(r.GetRight()-d,r.GetBottom()-d,d,d,0,90); p.AddArc(r.X,r.GetBottom()-d,d,d,90,90); p.CloseFigure();
    SolidBrush b(GColor(c,alpha)); g.FillPath(&b,&p); if(borderWidth>0){Pen pen(GColor(border,alpha),borderWidth);g.DrawPath(&pen,&p);}
}
void Line(Graphics& g,float x1,float y1,float x2,float y2,COLORREF c,float width=1){Pen p(GColor(c),width);g.DrawLine(&p,x1,y1,x2,y2);}
void Text(Graphics& g,const wstring& s,float x,float y,float size,COLORREF color=C_WHITE,int style=FontStyleRegular,float width=700,float height=48,StringAlignment align=StringAlignmentNear,BYTE alpha=255,StringAlignment vAlign=StringAlignmentNear){
    FontFamily family(L"Microsoft YaHei UI"); Font font(&family,size,style,UnitPixel); SolidBrush brush(GColor(color,alpha)); RectF box(x,y,width,height); StringFormat fmt; fmt.SetAlignment(align); fmt.SetLineAlignment(vAlign); fmt.SetTrimming(StringTrimmingEllipsisCharacter); g.DrawString(s.c_str(),(INT)s.size(),&font,box,&fmt,&brush);
}
