bool Hit(POINT p,float x,float y,float w,float h){return p.x>=x&&p.x<=x+w&&p.y>=y&&p.y<=y+h;}
float EaseMotion(float from,float to,ULONGLONG started,ULONGLONG now,ULONGLONG duration){float t=std::clamp((float)(now-started)/(float)duration,0.0f,1.0f);float eased=1.0f-std::pow(1.0f-t,3.0f);return from+(to-from)*eased;}
void UpdateButtonMotion(ButtonMotion& motion,ULONGLONG now){motion.hover=EaseMotion(motion.hoverFrom,motion.hoverTo,motion.hoverStarted,now,130);motion.press=EaseMotion(motion.pressFrom,motion.pressTo,motion.pressStarted,now,motion.pressTo>motion.pressFrom?70:150);}
void SetButtonMotion(int index,bool hover,bool press){if(index<0||index>=(int)g_buttonMotions.size())return;ULONGLONG now=GetTickCount64();ButtonMotion& motion=g_buttonMotions[index];UpdateButtonMotion(motion,now);float nextHover=hover?1.0f:0.0f,nextPress=press?1.0f:0.0f;if(motion.hoverTo!=nextHover){motion.hoverFrom=motion.hover;motion.hoverTo=nextHover;motion.hoverStarted=now;}if(motion.pressTo!=nextPress){motion.pressFrom=motion.press;motion.pressTo=nextPress;motion.pressStarted=now;}SetTimer(g_window,3,16,nullptr);}
bool UpdateButtonMotions(ULONGLONG now){bool running=false;for(auto& motion:g_buttonMotions){UpdateButtonMotion(motion,now);if((motion.hover!=motion.hoverTo&&now-motion.hoverStarted<130)||(motion.press!=motion.pressTo&&now-motion.pressStarted<(motion.pressTo>motion.pressFrom?70:150)))running=true;}return running;}
int ButtonAt(POINT p){for(int i=(int)g_buttonRects.size()-1;i>=0;--i){const RectF& r=g_buttonRects[i];if(Hit(p,r.X,r.Y,r.Width,r.Height))return i;}return -1;}
