wstring AppDirectory(){PWSTR p=nullptr;SHGetKnownFolderPath(FOLDERID_RoamingAppData,0,nullptr,&p);wstring d=p?p:L".";if(p)CoTaskMemFree(p);d+=L"\\NovaMemory";CreateDirectoryW(d.c_str(),nullptr);return d;}
wstring ConfigPath(){return AppDirectory()+L"\\settings.json";}
int JsonInt(const wstring& s,const wchar_t* key,int fallback){size_t p=s.find(key);if(p==wstring::npos)return fallback;p=s.find(L':',p);if(p==wstring::npos)return fallback;return _wtoi(s.c_str()+p+1);}
wstring JsonString(const wstring& s,const wchar_t* key){size_t p=s.find(key);if(p==wstring::npos)return L"";p=s.find(L':',p);if(p==wstring::npos)return L"";p=s.find(L'"',p);if(p==wstring::npos)return L"";size_t e=s.find(L'"',p+1);if(e==wstring::npos)return L"";return s.substr(p+1,e-p-1);}
void LoadConfig(){std::wifstream f(ConfigPath());wstring s((std::istreambuf_iterator<wchar_t>(f)),{});g_config.automatic=JsonInt(s,L"auto_optimize",0)!=0;g_config.threshold=std::clamp(JsonInt(s,L"threshold",80),50,95);g_config.aggressive=JsonInt(s,L"aggressive",0)!=0;g_config.allProcesses=JsonInt(s,L"all_processes",0)!=0;g_config.fullStartup=JsonInt(s,L"full_startup",0)!=0;g_config.theme=std::clamp(JsonInt(s,L"\"theme\"",0),0,2);g_config.opacity=std::clamp(JsonInt(s,L"\"opacity\"",96),70,100);g_config.accent=(COLORREF)std::clamp(JsonInt(s,L"\"accent\"",RGB(103,231,233)),0,0xFFFFFF);g_config.registerError=JsonString(s,L"\"register_error\"");}
bool SaveConfig(){std::wofstream f(ConfigPath());if(!f)return false;f<<L"{\n  \"auto_optimize\": "<<(g_config.automatic?1:0)<<L",\n  \"threshold\": "<<g_config.threshold<<L",\n  \"aggressive\": "<<(g_config.aggressive?1:0)<<L",\n  \"all_processes\": "<<(g_config.allProcesses?1:0)<<L",\n  \"full_startup\": "<<(g_config.fullStartup?1:0)<<L",\n  \"theme\": "<<g_config.theme<<L",\n  \"opacity\": "<<g_config.opacity<<L",\n  \"accent\": "<<(DWORD)g_config.accent<<L",\n  \"register_error\": \""<<g_config.registerError<<L"\"\n}\n";return (bool)f;}
void RefreshMemory(){MEMORYSTATUSEX m{sizeof(m)};if(GlobalMemoryStatusEx(&m)&&m.ullTotalPhys){g_preciseMemoryPercent=std::clamp(100.0*(double)(m.ullTotalPhys-m.ullAvailPhys)/(double)m.ullTotalPhys,0.0,100.0);g_memoryPercent=(int)std::lround(g_preciseMemoryPercent);g_totalGb=m.ullTotalPhys/1073741824.0;g_usedGb=(m.ullTotalPhys-m.ullAvailPhys)/1073741824.0;if(!g_memoryHistoryReady){g_memoryHistory.fill((float)g_preciseMemoryPercent);g_memoryHistoryReady=true;}else{g_memoryHistory[g_memoryHistoryNext]=(float)g_preciseMemoryPercent;g_memoryHistoryNext=(g_memoryHistoryNext+1)%g_memoryHistory.size();}}InvalidateRect(g_window,nullptr,FALSE);}
bool IsCritical(const wstring& name){static const wchar_t* names[]={L"system",L"registry",L"smss.exe",L"csrss.exe",L"wininit.exe",L"winlogon.exe",L"services.exe",L"lsass.exe",L"svchost.exe",L"dwm.exe",L"explorer.exe"};for(auto n:names)if(!_wcsicmp(name.c_str(),n))return true;return false;}
bool ProcessBelongsToCurrentUser(DWORD pid){HANDLE process=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid);if(!process)return false;HANDLE token=nullptr;bool same=false;if(OpenProcessToken(process,TOKEN_QUERY,&token)){DWORD bytes=0;GetTokenInformation(token,TokenUser,nullptr,0,&bytes);std::vector<BYTE> buffer(bytes);if(bytes&&GetTokenInformation(token,TokenUser,buffer.data(),bytes,&bytes)){HANDLE own=nullptr;if(OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&own)){DWORD ownBytes=0;GetTokenInformation(own,TokenUser,nullptr,0,&ownBytes);std::vector<BYTE> ownBuffer(ownBytes);if(ownBytes&&GetTokenInformation(own,TokenUser,ownBuffer.data(),ownBytes,&ownBytes))same=EqualSid(((TOKEN_USER*)buffer.data())->User.Sid,((TOKEN_USER*)ownBuffer.data())->User.Sid)!=FALSE;CloseHandle(own);}}CloseHandle(token);}CloseHandle(process);return same;}
void OptimizeMemory(bool automatic){bool expected=false;if(!g_optimizing.compare_exchange_strong(expected,true))return;int before=g_memoryPercent;bool aggressive=g_config.aggressive;std::thread([before,aggressive,automatic](){OptimizeResult* result=new OptimizeResult;result->before=before;result->automatic=automatic;DWORD self=GetCurrentProcessId();HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snap!=INVALID_HANDLE_VALUE){PROCESSENTRY32W e{sizeof(e)};if(Process32FirstW(snap,&e))do{wstring name=e.szExeFile;if(e.th32ProcessID<=4||e.th32ProcessID==self||IsCritical(name)||(!aggressive&&!ProcessBelongsToCurrentUser(e.th32ProcessID))){result->skipped++;continue;}HANDLE h=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_SET_QUOTA,FALSE,e.th32ProcessID);if(h){if(EmptyWorkingSet(h))result->processed++;else result->skipped++;CloseHandle(h);}else result->skipped++;}while(Process32NextW(snap,&e));CloseHandle(snap);}MEMORYSTATUSEX m{sizeof(m)};GlobalMemoryStatusEx(&m);result->after=(int)m.dwMemoryLoad;if(!PostMessageW(g_window,WM_OPTIMIZE_DONE,0,(LPARAM)result))delete result;}).detach();}

bool GetRegString(HKEY root,const wstring& path,const wstring& name,wstring& value,DWORD* valueType=nullptr,REGSAM view=0){HKEY h;if(RegOpenKeyExW(root,path.c_str(),0,KEY_QUERY_VALUE|view,&h)!=ERROR_SUCCESS)return false;DWORD type=0,size=0;LONG rc=RegQueryValueExW(h,name.c_str(),nullptr,&type,nullptr,&size);std::vector<wchar_t> b(size/sizeof(wchar_t)+2);if(rc==ERROR_SUCCESS)rc=RegQueryValueExW(h,name.c_str(),nullptr,&type,(LPBYTE)b.data(),&size);RegCloseKey(h);if(rc!=ERROR_SUCCESS||(type!=REG_SZ&&type!=REG_EXPAND_SZ))return false;value=b.data();if(valueType)*valueType=type;return true;}
void LoadComputerInfo(){g_computerInfo=ComputerInfo{};DWORD nameLength=MAX_COMPUTERNAME_LENGTH+1;wchar_t computerName[MAX_COMPUTERNAME_LENGTH+1]{};if(GetComputerNameW(computerName,&nameLength))g_computerInfo.name=computerName;else g_computerInfo.name=L"未知设备";GetRegString(HKEY_LOCAL_MACHINE,L"HARDWARE\\DESCRIPTION\\System\\CentralProcessor\\0",L"ProcessorNameString",g_computerInfo.processor);if(g_computerInfo.processor.empty())g_computerInfo.processor=L"无法读取处理器信息";std::vector<wstring> graphics;for(DWORD i=0;i<8;i++){DISPLAY_DEVICEW device{sizeof(device)};if(!EnumDisplayDevicesW(nullptr,i,&device,0))break;if((device.StateFlags&DISPLAY_DEVICE_ATTACHED_TO_DESKTOP)&&!(device.StateFlags&DISPLAY_DEVICE_MIRRORING_DRIVER)){wstring name=device.DeviceString;if(!name.empty()&&std::find(graphics.begin(),graphics.end(),name)==graphics.end())graphics.push_back(std::move(name));}}if(graphics.empty())g_computerInfo.graphics=L"未检测到显示适配器";else for(size_t i=0;i<graphics.size()&&i<2;i++){if(i)g_computerInfo.graphics+=L" · ";g_computerInfo.graphics+=graphics[i];}wstring product,version,build;const wstring windowsKey=L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion";GetRegString(HKEY_LOCAL_MACHINE,windowsKey,L"ProductName",product);GetRegString(HKEY_LOCAL_MACHINE,windowsKey,L"DisplayVersion",version);GetRegString(HKEY_LOCAL_MACHINE,windowsKey,L"CurrentBuildNumber",build);g_computerInfo.windows=product.empty()?L"Windows":product;if(!version.empty())g_computerInfo.windows+=L" · "+version;if(!build.empty())g_computerInfo.windows+=L" · 构建 "+build;SYSTEM_INFO systemInfo{};GetNativeSystemInfo(&systemInfo);g_computerInfo.logicalProcessors=systemInfo.dwNumberOfProcessors;switch(systemInfo.wProcessorArchitecture){case PROCESSOR_ARCHITECTURE_AMD64:g_computerInfo.architecture=L"64 位 x64";break;
#ifdef PROCESSOR_ARCHITECTURE_ARM64
case PROCESSOR_ARCHITECTURE_ARM64:g_computerInfo.architecture=L"64 位 ARM";break;
#endif
case PROCESSOR_ARCHITECTURE_INTEL:g_computerInfo.architecture=L"32 位 x86";break;default:g_computerInfo.architecture=L"未知架构";break;}MEMORYSTATUSEX memory{sizeof(memory)};if(GlobalMemoryStatusEx(&memory)){g_computerInfo.memoryTotal=memory.ullTotalPhys/1073741824.0;g_computerInfo.memoryUsed=(memory.ullTotalPhys-memory.ullAvailPhys)/1073741824.0;}wchar_t windowsDirectory[MAX_PATH]{};if(GetWindowsDirectoryW(windowsDirectory,MAX_PATH)>=3){wstring systemDrive(windowsDirectory,3);ULARGE_INTEGER freeAvailable{},total{},totalFree{};if(GetDiskFreeSpaceExW(systemDrive.c_str(),&freeAvailable,&total,&totalFree)){g_computerInfo.diskTotal=total.QuadPart/1073741824.0;g_computerInfo.diskFree=freeAvailable.QuadPart/1073741824.0;}}}
wstring ExpandPath(wstring value){DWORD n=ExpandEnvironmentStringsW(value.c_str(),nullptr,0);if(n){std::vector<wchar_t>b(n);ExpandEnvironmentStringsW(value.c_str(),b.data(),n);value=b.data();}return value;}
bool MissingExecutable(const wstring& command){wstring s=command;while(!s.empty()&&iswspace(s.front()))s.erase(s.begin());wstring path;if(!s.empty()&&s.front()==L'"'){size_t end=s.find(L'"',1);if(end!=wstring::npos)path=s.substr(1,end-1);}else{size_t end=std::wstring::npos;for(size_t i=0;i+4<=s.size();++i)if(!_wcsnicmp(s.c_str()+i,L".exe",4)){end=i+4;break;}if(end!=wstring::npos)path=s.substr(0,end);}if(path.empty())return false;path=ExpandPath(path);return GetFileAttributesW(path.c_str())==INVALID_FILE_ATTRIBUTES;}
void AddRunKeys(std::vector<std::pair<HKEY,wstring>>& keys,bool deep){keys.push_back({HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run"});if(deep){keys.push_back({HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\RunOnce"});keys.push_back({HKEY_LOCAL_MACHINE,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run"});keys.push_back({HKEY_LOCAL_MACHINE,L"Software\\Microsoft\\Windows\\CurrentVersion\\RunOnce"});}}
