bool KeyHasSubKeys(HKEY root,const wstring& path,REGSAM view=0){HKEY h;if(RegOpenKeyExW(root,path.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return true;DWORD count=1;WCHAR name[2]{};DWORD length=2;LONG rc=RegEnumKeyExW(h,0,name,&length,nullptr,nullptr,nullptr,nullptr);RegCloseKey(h);return rc==ERROR_SUCCESS;}

void AddIssue(std::vector<RegistryItem>& out,HKEY root,const wstring& path,const wstring& name,const wstring& value,bool deleteKey,int kind,const wstring& title,const wstring& detail,REGSAM view=0){RegistryItem item;item.root=root;item.path=path;item.name=name;item.value=value;item.deleteKey=deleteKey;item.kind=kind;item.title=title;item.detail=detail;item.view=view;out.push_back(std::move(item));}

// kind: 1 = dead startup command, 2 = orphaned uninstall entry, 3 = broken file
// association, 4 = dead App Paths entry. Every probe is a real filesystem or
// registry lookup, so the numbers on screen are measured, not guessed.
void ScanStartupIssues(std::vector<RegistryItem>& out){std::vector<std::pair<HKEY,wstring>> keys;AddRunKeys(keys,true);const wchar_t* scopes[]={L"用户 Run",L"用户 RunOnce",L"系统 Run",L"系统 RunOnce"};REGSAM views[]={KEY_WOW64_64KEY,KEY_WOW64_32KEY};for(auto& k:keys){for(REGSAM view:views){HKEY h;if(RegOpenKeyExW(k.first,k.second.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)continue;DWORD count=0,maxName=0,maxValue=0;RegQueryInfoKeyW(h,nullptr,nullptr,nullptr,nullptr,nullptr,nullptr,&count,&maxName,&maxValue,nullptr,nullptr);std::vector<wchar_t> name(maxName+2),value(maxValue/sizeof(wchar_t)+2);for(DWORD i=0;i<count;i++){DWORD ns=(DWORD)name.size(),vs=(DWORD)(value.size()*sizeof(wchar_t)),type=0;if(RegEnumValueW(h,i,name.data(),&ns,nullptr,&type,(LPBYTE)value.data(),&vs)!=ERROR_SUCCESS||(type!=REG_SZ&&type!=REG_EXPAND_SZ))continue;if(!MissingExecutable(value.data()))continue;AddIssue(out,k.first,k.second,wstring(name.data(),ns),wstring(value.data()),false,1,wstring(name.data(),ns),wstring(value.data()),view);}RegCloseKey(h);}if(k.second.find(L"RunOnce")!=wstring::npos)break;}}

void ScanUninstallIssues(HKEY root,const wstring& base,REGSAM view,std::vector<RegistryItem>& out){HKEY h;if(RegOpenKeyExW(root,base.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return;for(DWORD index=0;;index++){wchar_t name[512]{};DWORD length=512;if(RegEnumKeyExW(h,index,name,&length,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;wstring sub=base+L"\\"+name;wstring display,location,icon;GetRegString(root,sub,L"DisplayName",display);if(display.empty())continue;bool hasLocation=GetRegString(root,sub,L"InstallLocation",location)&&!location.empty();bool hasIcon=GetRegString(root,sub,L"DisplayIcon",icon)&&!icon.empty();wstring target;if(hasLocation)target=location;else if(hasIcon){target=icon;size_t comma=target.find(L',');if(comma!=wstring::npos)target.resize(comma);}if(target.empty())continue;while(!target.empty()&&iswspace(target.back()))target.pop_back();if(target.size()>1&&target.front()==L'"'){target.erase(target.begin());size_t quote=target.find(L'"');if(quote!=wstring::npos)target.resize(quote);}if(PathPresent(target))continue;if(KeyHasSubKeys(root,sub,view))continue;AddIssue(out,root,sub,L"",display,true,2,display,target,view);}RegCloseKey(h);}

void ScanFileAssocIssues(std::vector<RegistryItem>& out){const wstring base=L"Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\FileExts";HKEY h;if(RegOpenKeyExW(HKEY_CURRENT_USER,base.c_str(),0,KEY_READ,&h)!=ERROR_SUCCESS)return;for(DWORD index=0;;index++){wchar_t ext[256]{};DWORD length=256;if(RegEnumKeyExW(h,index,ext,&length,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;wstring userChoice=base+L"\\"+ext+L"\\UserChoice";wstring progId;if(!GetRegString(HKEY_CURRENT_USER,userChoice,L"ProgId",progId)||progId.empty())continue;if(KeyExists(HKEY_CURRENT_USER,L"Software\\Classes\\"+progId)||KeyExists(HKEY_CLASSES_ROOT,progId))continue;if(KeyHasSubKeys(HKEY_CURRENT_USER,userChoice))continue;AddIssue(out,HKEY_CURRENT_USER,userChoice,L"",progId,true,3,wstring(L"无效文件关联 · ")+ext,progId);}RegCloseKey(h);}

void ScanAppPathIssues(HKEY root,REGSAM view,std::vector<RegistryItem>& out){const wstring base=L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\App Paths";HKEY h;if(RegOpenKeyExW(root,base.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return;for(DWORD index=0;;index++){wchar_t name[512]{};DWORD length=512;if(RegEnumKeyExW(h,index,name,&length,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;wstring sub=base+L"\\"+name;wstring target;if(!GetRegString(root,sub,L"",target)||target.empty())continue;if(PathPresent(target))continue;if(KeyHasSubKeys(root,sub,view))continue;AddIssue(out,root,sub,L"",target,true,4,wstring(L"失效应用路径 · ")+name,target,view);}RegCloseKey(h);}

std::vector<RegistryItem> ScanRegistry(bool deep){std::vector<RegistryItem> out;ScanStartupIssues(out);const wstring uninstall=L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall";ScanUninstallIssues(HKEY_CURRENT_USER,uninstall,0,out);ScanUninstallIssues(HKEY_LOCAL_MACHINE,uninstall,KEY_WOW64_64KEY,out);ScanUninstallIssues(HKEY_LOCAL_MACHINE,uninstall+L"\\WOW6432Node",KEY_WOW64_64KEY,out);ScanFileAssocIssues(out);ScanAppPathIssues(HKEY_LOCAL_MACHINE,KEY_WOW64_64KEY,out);ScanAppPathIssues(HKEY_CURRENT_USER,0,out);(void)deep;return out;}
wstring EscapeReg(const wstring& s){wstring out;for(wchar_t c:s){if(c==L'\\'||c==L'"')out.push_back(L'\\');if(c==L'\n'||c==L'\r')continue;out.push_back(c);}return out;}
void WriteHexBlock(std::wofstream& f,const wstring& name,const wstring& prefix,const BYTE* data,DWORD bytes){f<<name<<L"="<<prefix;for(DWORD i=0;i<bytes;i++){if(i)f<<L",";f<<std::hex<<std::setw(2)<<std::setfill(L'0')<<(int)data[i]<<std::dec;}f<<L"\r\n";}

void DumpKeyValues(std::wofstream& f,HKEY root,const wstring& path,REGSAM view){HKEY h;if(RegOpenKeyExW(root,path.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return;DWORD count=0,maxName=0,maxValue=0;RegQueryInfoKeyW(h,nullptr,nullptr,nullptr,nullptr,nullptr,nullptr,&count,&maxName,&maxValue,nullptr,nullptr);std::vector<wchar_t> name(maxName+2);std::vector<BYTE> data(maxValue+16);for(DWORD i=0;i<count;i++){DWORD ns=(DWORD)name.size(),size=(DWORD)data.size(),type=0;if(RegEnumValueW(h,i,name.data(),&ns,nullptr,&type,data.data(),&size)!=ERROR_SUCCESS)continue;wstring n=ns?L"\""+EscapeReg(wstring(name.data(),ns))+L"\"":L"@";if(type==REG_SZ){f<<n<<L"=\""<<EscapeReg(wstring((const wchar_t*)data.data()))<<L"\"\r\n";}else if(type==REG_EXPAND_SZ){WriteHexBlock(f,n,L"hex(2):",data.data(),size);}else if(type==REG_DWORD&&size>=4){DWORD v=0;memcpy(&v,data.data(),4);f<<n<<L"=dword:"<<std::hex<<std::setw(8)<<std::setfill(L'0')<<v<<std::dec<<L"\r\n";}else if(type==REG_QWORD&&size>=8){WriteHexBlock(f,n,L"hex(b):",data.data(),8);}else if(type==REG_MULTI_SZ){WriteHexBlock(f,n,L"hex(7):",data.data(),size);}else{WriteHexBlock(f,n,L"hex:",data.data(),size);}}RegCloseKey(h);}

bool BackupRegistry(const std::vector<RegistryItem>& items,wstring& outputPath){outputPath=AppDirectory()+L"\\RegistryBackup-"+std::to_wstring((long long)GetTickCount64())+L".reg";std::wofstream f(outputPath,std::ios::binary);if(!f)return false;f.put((wchar_t)0xFEFF);f<<L"Windows Registry Editor Version 5.00\r\n\r\n";for(const auto& i:items){f<<L"["<<(i.root==HKEY_CURRENT_USER?L"HKEY_CURRENT_USER":L"HKEY_LOCAL_MACHINE")<<L"\\"<<i.path<<L"]\r\n";if(i.deleteKey){DumpKeyValues(f,i.root,i.path,i.view);f<<L"\r\n";continue;}wstring n=i.name.empty()?L"@":L"\""+EscapeReg(i.name)+L"\"";if(i.type==REG_SZ){f<<n<<L"=\""<<EscapeReg(i.value)<<L"\"\r\n\r\n";}else{WriteHexBlock(f,n,L"hex(2):",(const BYTE*)i.value.c_str(),(DWORD)((i.value.size()+1)*sizeof(wchar_t)));f<<L"\r\n";}}f.flush();return (bool)f;}
bool DeleteRegistryItems(const std::vector<RegistryItem>& items,int& removed,int& failed){removed=0;failed=0;for(const auto&i:items){LONG rc=ERROR_FILE_NOT_FOUND;if(i.deleteKey){rc=RegDeleteKeyExW(i.root,i.path.c_str(),i.view,0);}else{HKEY h;if(RegOpenKeyExW(i.root,i.path.c_str(),0,KEY_SET_VALUE|i.view,&h)==ERROR_SUCCESS){rc=RegDeleteValueW(h,i.name.c_str());RegCloseKey(h);}}if(rc==ERROR_SUCCESS)removed++;else failed++;}return true;}

std::vector<RegistryItem> g_registryItems;
bool g_registryBusy=false,g_registryScanned=false;
wstring g_registryStatus=L"尚未体检 · 点击「重新扫描」检查四类失效记录";
void PreviewRegistryCleanup(){if(g_registryBusy){ShowToast(L"体检仍在进行，请稍候");return;}if(g_registryItems.empty()&&!g_registryScanned){ShowToast(L"先点「重新扫描」跑一次注册表体检");return;}if(g_registryItems.empty()){ShowToast(L"体检通过：没有发现失效注册表记录");return;}int startup=0,orphan=0,assoc=0,path=0;for(auto& i:g_registryItems){if(i.kind==1)startup++;else if(i.kind==2)orphan++;else if(i.kind==3)assoc++;else path++;}std::wostringstream body;body<<L"共 "<<g_registryItems.size()<<L" 项失效记录：失效启动项 "<<startup<<L" · 残留卸载项 "<<orphan<<L" · 无效文件关联 "<<assoc<<L" · 失效应用路径 "<<path<<L"\n\n";int shown=0;for(auto& i:g_registryItems){if(shown>=4)break;body<<L"• "<<i.title<<L"\n";shown++;}if((int)g_registryItems.size()>shown)body<<L"… 还有 "<<(int)g_registryItems.size()-shown<<L" 项\n";body<<L"执行前会生成可导入的 .reg 备份。";g_pendingRegistryItems=g_registryItems;ShowPrompt(PromptKind::RegistryCleanup,L"注册表体检结果",body.str());}
void StartRegistryScan(){if(g_registryBusy)return;g_registryBusy=true;g_registryStatus=L"正在逐项体检注册表…";InvalidateRect(g_window,nullptr,FALSE);std::thread([](){auto* result=new RegistryScanResult;result->items=ScanRegistry(false);if(!PostMessageW(g_window,WM_REGISTRY_SCAN_DONE,0,(LPARAM)result))delete result;}).detach();}

void ConfirmRegistryCleanup();void OpenRegistryEditor(){HINSTANCE result=ShellExecuteW(g_window,L"open",L"regedit.exe",nullptr,nullptr,SW_SHOWNORMAL);if((INT_PTR)result<=32)ShowToast(L"无法打开注册表编辑器",true);else{g_lastAction=L"已打开注册表编辑器";ShowToast(L"已打开注册表编辑器");}}
void ConfirmRegistryCleanup(){wstring backup;if(!BackupRegistry(g_pendingRegistryItems,backup)){DismissPrompt();ShowToast(L"注册表备份失败，未执行清理",true);return;}int removed=0,failed=0;DeleteRegistryItems(g_pendingRegistryItems,removed,failed);g_lastAction=L"注册表体检清理完成 · 已备份";DismissPrompt();ShowToast(L"已清理 "+std::to_wstring(removed)+L" 项"+(failed?L" · "+std::to_wstring(failed)+L" 项需管理员权限":L"")+L" · 备份已创建");g_registryItems.clear();g_registryScanned=false;StartRegistryScan();}

wstring CurrentStartupFolder(){PWSTR p=nullptr;SHGetKnownFolderPath(FOLDERID_Startup,0,nullptr,&p);wstring s=p?p:L"";if(p)CoTaskMemFree(p);return s;}
wstring CommonStartupFolder(){PWSTR p=nullptr;SHGetKnownFolderPath(FOLDERID_CommonStartup,0,nullptr,&p);wstring s=p?p:L"";if(p)CoTaskMemFree(p);return s;}
void ReadStartupRegistryKey(HKEY root,const wstring& path,const wstring& scope,REGSAM view,std::vector<StartupItem>& out){auto read=[&](const wstring& actual,bool enabled){HKEY h;if(RegOpenKeyExW(root,actual.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return;DWORD c=0,mn=0,mv=0;RegQueryInfoKeyW(h,nullptr,nullptr,nullptr,nullptr,nullptr,nullptr,&c,&mn,&mv,nullptr,nullptr);std::vector<wchar_t> n(mn+2),v(mv/sizeof(wchar_t)+2);for(DWORD i=0;i<c;i++){DWORD ns=(DWORD)n.size(),vs=(DWORD)(v.size()*sizeof(wchar_t)),type=0;if(RegEnumValueW(h,i,n.data(),&ns,nullptr,&type,(LPBYTE)v.data(),&vs)==ERROR_SUCCESS&&(type==REG_SZ||type==REG_EXPAND_SZ)){StartupItem item;item.registry=true;item.enabled=enabled;item.root=root;item.path=path;item.name.assign(n.data(),ns);item.value.assign(v.data());item.type=type;item.source=scope;item.registryView=view;out.push_back(std::move(item));}}RegCloseKey(h);};read(path,true);read(path+L"\\NovaMemoryDisabled",false);}
bool IsStartupFile(const wchar_t* name){const wchar_t* ext=wcsrchr(name,L'.');if(!ext)return false;static const wchar_t* allowed[]={L".lnk",L".url",L".exe",L".bat",L".cmd",L".vbs",L".js",L".wsf",L".ps1"};for(auto e:allowed)if(!_wcsicmp(ext,e))return true;return false;}
void ReadStartupFolder(const wstring& folder,const wstring& source,std::vector<StartupItem>& out){if(folder.empty())return;WIN32_FIND_DATAW d;HANDLE h=FindFirstFileW((folder+L"\\*").c_str(),&d);if(h==INVALID_HANDLE_VALUE)return;do{if(d.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)continue;if(!wcscmp(d.cFileName,L".")||!wcscmp(d.cFileName,L".."))continue;wstring name=d.cFileName;bool enabled=true;if(name.size()>9&&_wcsicmp(name.c_str()+name.size()-9,L".disabled")==0){enabled=false;name.resize(name.size()-9);}if(!IsStartupFile(name.c_str()))continue;StartupItem item;item.registry=false;item.filePath=folder+L"\\"+d.cFileName;item.enabled=enabled;item.name=name;item.source=source;out.push_back(std::move(item));}while(FindNextFileW(h,&d));FindClose(h);}
void RefreshStartupItems(){g_startupItems.clear();const wstring userRun=L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",userOnce=L"Software\\Microsoft\\Windows\\CurrentVersion\\RunOnce";ReadStartupRegistryKey(HKEY_CURRENT_USER,userRun,L"用户 Run · 64 位",KEY_WOW64_64KEY,g_startupItems);ReadStartupRegistryKey(HKEY_CURRENT_USER,userOnce,L"用户 RunOnce · 64 位",KEY_WOW64_64KEY,g_startupItems);ReadStartupRegistryKey(HKEY_CURRENT_USER,userRun,L"用户 Run · 32 位",KEY_WOW64_32KEY,g_startupItems);ReadStartupRegistryKey(HKEY_CURRENT_USER,userOnce,L"用户 RunOnce · 32 位",KEY_WOW64_32KEY,g_startupItems);if(g_config.fullStartup){const wstring systemRun=L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",systemOnce=L"Software\\Microsoft\\Windows\\CurrentVersion\\RunOnce";ReadStartupRegistryKey(HKEY_LOCAL_MACHINE,systemRun,L"系统 Run · 64 位",KEY_WOW64_64KEY,g_startupItems);ReadStartupRegistryKey(HKEY_LOCAL_MACHINE,systemOnce,L"系统 RunOnce · 64 位",KEY_WOW64_64KEY,g_startupItems);ReadStartupRegistryKey(HKEY_LOCAL_MACHINE,systemRun,L"系统 Run · 32 位",KEY_WOW64_32KEY,g_startupItems);ReadStartupRegistryKey(HKEY_LOCAL_MACHINE,systemOnce,L"系统 RunOnce · 32 位",KEY_WOW64_32KEY,g_startupItems);}ReadStartupFolder(CurrentStartupFolder(),L"用户启动文件夹",g_startupItems);if(g_config.fullStartup)ReadStartupFolder(CommonStartupFolder(),L"公共启动文件夹",g_startupItems);std::stable_sort(g_startupItems.begin(),g_startupItems.end(),[](const auto&a,const auto&b){return _wcsicmp(a.name.c_str(),b.name.c_str())<0;});g_scroll=0;g_selectedStartup=-1;}
bool SetStartupEnabled(StartupItem& item,bool enabled){if(item.registry){wstring disabled=item.path+L"\\NovaMemoryDisabled";REGSAM view=item.registryView;if(enabled&&!item.enabled){wstring value;DWORD type=REG_SZ;if(!GetRegString(item.root,disabled,item.name,value,&type,view))return false;HKEY dest;if(RegCreateKeyExW(item.root,item.path.c_str(),0,nullptr,0,KEY_SET_VALUE|view,nullptr,&dest,nullptr)!=ERROR_SUCCESS)return false;LONG rc=RegSetValueExW(dest,item.name.c_str(),0,type,(const BYTE*)value.c_str(),(DWORD)((value.size()+1)*sizeof(wchar_t)));RegCloseKey(dest);if(rc!=ERROR_SUCCESS)return false;HKEY src;if(RegOpenKeyExW(item.root,disabled.c_str(),0,KEY_SET_VALUE|view,&src)!=ERROR_SUCCESS)return false;RegDeleteValueW(src,item.name.c_str());RegCloseKey(src);return true;}if(!enabled&&item.enabled){HKEY src;if(RegOpenKeyExW(item.root,item.path.c_str(),0,KEY_QUERY_VALUE|KEY_SET_VALUE|view,&src)!=ERROR_SUCCESS)return false;DWORD type=0,size=0;LONG rc=RegQueryValueExW(src,item.name.c_str(),nullptr,&type,nullptr,&size);std::vector<BYTE> data(size);if(rc==ERROR_SUCCESS)rc=RegQueryValueExW(src,item.name.c_str(),nullptr,&type,data.data(),&size);RegCloseKey(src);if(rc!=ERROR_SUCCESS)return false;HKEY dst;if(RegCreateKeyExW(item.root,disabled.c_str(),0,nullptr,0,KEY_SET_VALUE|view,nullptr,&dst,nullptr)!=ERROR_SUCCESS)return false;rc=RegSetValueExW(dst,item.name.c_str(),0,type,data.data(),size);RegCloseKey(dst);if(rc!=ERROR_SUCCESS)return false;if(RegOpenKeyExW(item.root,item.path.c_str(),0,KEY_SET_VALUE|view,&src)!=ERROR_SUCCESS)return false;rc=RegDeleteValueW(src,item.name.c_str());RegCloseKey(src);return rc==ERROR_SUCCESS;}return true;}wstring target=item.filePath;if(enabled&&!item.enabled){size_t n=target.rfind(L".disabled");if(n!=wstring::npos)target.erase(n);}else if(!enabled&&item.enabled)target+=L".disabled";else return true;return MoveFileW(item.filePath.c_str(),target.c_str())!=FALSE;}
std::vector<ProcessItem> ScanProcesses(bool allProcesses){std::vector<ProcessItem> items;HANDLE snap=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snap==INVALID_HANDLE_VALUE)return items;PROCESSENTRY32W e{sizeof(e)};if(Process32FirstW(snap,&e))do{wstring name=e.szExeFile;if(e.th32ProcessID<=4||e.th32ProcessID==GetCurrentProcessId()||IsCritical(name))continue;bool own=ProcessBelongsToCurrentUser(e.th32ProcessID);if(!allProcesses&&!own)continue;SIZE_T bytes=0;HANDLE h=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION|PROCESS_VM_READ,FALSE,e.th32ProcessID);if(h){PROCESS_MEMORY_COUNTERS pm{sizeof(pm)};if(GetProcessMemoryInfo(h,&pm,sizeof(pm)))bytes=pm.WorkingSetSize;CloseHandle(h);}items.push_back({e.th32ProcessID,name,bytes,own});}while(Process32NextW(snap,&e));CloseHandle(snap);std::sort(items.begin(),items.end(),[](const auto&a,const auto&b){return a.memory>b.memory;});return items;}
void RefreshProcesses(){ULONGLONG generation=++g_processRefreshGeneration;bool allProcesses=g_config.allProcesses;g_processLoading=true;InvalidateRect(g_window,nullptr,FALSE);std::thread([generation,allProcesses](){auto* result=new ProcessRefreshResult;result->generation=generation;result->items=ScanProcesses(allProcesses);if(!PostMessageW(g_window,WM_PROCESS_REFRESH_DONE,0,(LPARAM)result))delete result;}).detach();}

void DrawButton(Graphics& g,RectF r,const wstring& label,bool primary=false,bool selected=false){int id=(int)g_buttonRects.size();g_buttonRects.push_back(r);if(g_buttonMotions.size()<=(size_t)id)g_buttonMotions.resize(id+1);ButtonMotion& motion=g_buttonMotions[id];UpdateButtonMotion(motion,GetTickCount64());float scale=1.0f-0.035f*motion.press;RectF visual=r;visual.X+=(r.Width-r.Width*scale)*0.5f;visual.Y+=(r.Height-r.Height*scale)*0.5f-1.6f*motion.hover;visual.Width*=scale;visual.Height*=scale;COLORREF base=primary?C_CYAN:(selected?C_PANEL_HI:Blend(C_PANEL,C_BG,0.05f));COLORREF c=Blend(base,primary?RGB(139,246,246):C_PANEL_HI,motion.hover*0.62f);if(motion.press>0)c=Blend(c,primary?C_CYAN_DARK:C_PANEL,motion.press*0.18f);COLORREF border=Blend(selected?C_CYAN_DARK:RGB(30,66,76),C_CYAN_DARK,motion.hover*0.72f);RoundRect(g,visual,c,12,border,1);Text(g,label,visual.X,visual.Y,14,primary?ContrastText(c):C_WHITE,FontStyleBold,visual.Width,visual.Height,StringAlignmentCenter,255,StringAlignmentCenter);}
void DrawToggle(Graphics& g,float x,float y,bool on){ULONGLONG now=GetTickCount64();float target=on?1.0f:0.0f;if(!g_toggleInitialized){g_toggleValue=g_toggleFrom=g_toggleTo=target;g_toggleInitialized=true;}else{g_toggleValue=EaseMotion(g_toggleFrom,g_toggleTo,g_toggleStarted,now,1000);if(g_toggleTo!=target){g_toggleFrom=g_toggleValue;g_toggleTo=target;g_toggleStarted=now;SetTimer(g_window,5,16,nullptr);}}COLORREF track=Blend(RGB(52,72,80),C_CYAN_DARK,g_toggleValue);RoundRect(g,R(x,y,48,26),track,13);RoundRect(g,R(x+3+22*g_toggleValue,y+3,20,20),RGB(239,251,250),10);}
