void RefreshComputerUsage(){MEMORYSTATUSEX memory{sizeof(memory)};if(GlobalMemoryStatusEx(&memory)){g_computerInfo.memoryTotal=memory.ullTotalPhys/1073741824.0;g_computerInfo.memoryUsed=(memory.ullTotalPhys-memory.ullAvailPhys)/1073741824.0;}wchar_t windowsDirectory[MAX_PATH]{};if(GetWindowsDirectoryW(windowsDirectory,MAX_PATH)>=3){wstring systemDrive(windowsDirectory,3);ULARGE_INTEGER freeAvailable{},total{},totalFree{};if(GetDiskFreeSpaceExW(systemDrive.c_str(),&freeAvailable,&total,&totalFree)){g_computerInfo.diskTotal=total.QuadPart/1073741824.0;g_computerInfo.diskFree=freeAvailable.QuadPart/1073741824.0;}}}
wstring FormatGb(double value){std::wostringstream text;text<<std::fixed<<std::setprecision(1)<<value<<L" GB";return text.str();}
void SampleCpu(){FILETIME idleTime{},kernelTime{},userTime{};if(!GetSystemTimes(&idleTime,&kernelTime,&userTime))return;auto toTicks=[](const FILETIME& time){ULARGE_INTEGER ticks;ticks.LowPart=time.dwLowDateTime;ticks.HighPart=time.dwHighDateTime;return ticks.QuadPart;};ULONGLONG idle=toTicks(idleTime),kernel=toTicks(kernelTime),user=toTicks(userTime);if(g_cpuKernelSample||g_cpuUserSample){ULONGLONG totalDelta=(kernel-g_cpuKernelSample)+(user-g_cpuUserSample);ULONGLONG idleDelta=idle-g_cpuIdleSample;if(totalDelta>0)g_cpuPercent=std::clamp(100.0*(double)(totalDelta-idleDelta)/(double)totalDelta,0.0,100.0);}g_cpuIdleSample=idle;g_cpuKernelSample=kernel;g_cpuUserSample=user;}
