void DrawMemoryChart(Graphics& g,float x,float y,float width,float height){RoundRect(g,R(x,y,width,height),Blend(C_PANEL,C_BG,0.14f),12);Text(g,L"内存波动",x+13,y+7,10,C_MUTED,FontStyleBold,90,18);float low=100,high=0;for(float value:g_memoryHistory){low=std::min(low,value);high=std::max(high,value);}low=std::max(0.0f,low-2.0f);high=std::min(100.0f,high+2.0f);if(high-low<8){float middle=(high+low)/2;low=std::max(0.0f,middle-4);high=std::min(100.0f,low+8);low=std::max(0.0f,high-8);}std::wostringstream range;range<<std::lround(low)<<L"–"<<std::lround(high)<<L"% · 近60秒";Text(g,range.str(),x+width-148,y+7,9,C_MUTED,FontStyleRegular,135,18,StringAlignmentFar);float px=x+14,py=y+27,pw=width-28,ph=height-36;for(int i=1;i<=2;i++)Line(g,px,py+ph*i/3.0f,px+pw,py+ph*i/3.0f,Blend(C_PANEL_HI,C_MUTED,0.42f));std::array<PointF,240> points{};for(size_t i=0;i<points.size();i++){float value=g_memoryHistory[(g_memoryHistoryNext+i)%g_memoryHistory.size()];float t=(value-low)/std::max(1.0f,high-low);points[i]=PointF(px+pw*i/(points.size()-1),py+ph*(1.0f-t));}GraphicsPath fill;fill.AddLine(PointF(px,py+ph),points.front());fill.AddCurve(points.data(),(INT)points.size(),0.38f);fill.AddLine(points.back(),PointF(px+pw,py+ph));fill.CloseFigure();SolidBrush wash(Color(42,103,231,233));g.FillPath(&wash,&fill);Pen line(GColor(C_CYAN),2);line.SetStartCap(LineCapRound);line.SetEndCap(LineCapRound);GraphicsPath curve;curve.AddCurve(points.data(),(INT)points.size(),0.38f);g.DrawPath(&line,&curve);Dot(g,points.back().X-3,points.back().Y-3,6,C_CYAN);}
