wstring FormatBytes(ULONGLONG bytes){wchar_t buffer[48];if(bytes>=1073741824ULL)swprintf_s(buffer,48,L"%.2f GB",bytes/1073741824.0);else if(bytes>=1048576ULL)swprintf_s(buffer,48,L"%.1f MB",bytes/1048576.0);else swprintf_s(buffer,48,L"%llu KB",bytes/1024ULL);return buffer;}
wstring EnvPath(const wchar_t* name){wchar_t buffer[32768];DWORD length=GetEnvironmentVariableW(name,buffer,32768);return length?wstring(buffer,length):wstring();}
bool IsCacheFileName(const wstring& name){return name.rfind(L"thumbcache_",0)==0||name.rfind(L"iconcache_",0)==0;}
std::vector<CacheEntry> CacheTargets(){std::vector<CacheEntry> targets;auto add=[&](const wchar_t* label,const wstring& path,bool cacheFilesOnly=false){if(!path.empty())targets.push_back({label,path,0,0,false,false,cacheFilesOnly});};wstring local=EnvPath(L"LOCALAPPDATA"),root=EnvPath(L"SystemRoot");add(L"用户临时文件",EnvPath(L"TEMP"));if(!root.empty())add(L"系统临时文件",root+L"\\Temp");if(!local.empty()){add(L"DirectX 着色器缓存",local+L"\\D3DSCache");add(L"错误报告缓存",local+L"\\Microsoft\\Windows\\WER");add(L"缩略图与图标缓存",local+L"\\Microsoft\\Windows\\Explorer",true);add(L"Edge 浏览器缓存",local+L"\\Microsoft\\Edge\\User Data\\Default\\Cache");add(L"Chrome 浏览器缓存",local+L"\\Google\\Chrome\\User Data\\Default\\Cache");}if(!root.empty())add(L"Windows 更新下载缓存",root+L"\\SoftwareDistribution\\Download");targets.push_back({L"回收站",L"",0,0,false,true,false});return targets;}
void MeasureCache(CacheEntry& entry){std::error_code ec;if(entry.recycleBin){SHQUERYRBINFO info{sizeof(info)};if(SHQueryRecycleBinW(nullptr,&info)==S_OK){entry.bytes=(ULONGLONG)info.i64Size;entry.files=(DWORD)info.i64NumItems;entry.available=true;}return;}if(!fs::is_directory(entry.path,ec))return;entry.available=true;fs::recursive_directory_iterator it(entry.path,fs::directory_options::skip_permission_denied,ec),end;while(it!=end){if(ec){ec.clear();it.increment(ec);continue;}std::error_code local;if(it->is_regular_file(local)&&(!entry.cacheFilesOnly||IsCacheFileName(it->path().filename().wstring()))){auto size=it->file_size(local);if(!local){entry.bytes+=size;entry.files++;}}it.increment(ec);}}
void CleanCacheEntry(CacheEntry& entry,CacheCleanResult& result){std::error_code ec;if(entry.recycleBin)return;if(!fs::is_directory(entry.path,ec))return;std::vector<fs::path> files;fs::recursive_directory_iterator it(entry.path,fs::directory_options::skip_permission_denied,ec),end;while(it!=end){if(ec){ec.clear();it.increment(ec);continue;}std::error_code local;if(it->is_regular_file(local)&&(!entry.cacheFilesOnly||IsCacheFileName(it->path().filename().wstring())))files.push_back(it->path());it.increment(ec);}for(auto& file:files){std::error_code removeEc;auto size=fs::file_size(file,removeEc);ULONGLONG bytes=removeEc?0:size;if(fs::remove(file,removeEc)){result.freed+=bytes;result.removed++;}else result.skipped++;}}
