void StartCacheClean(){if(g_cacheBusy)return;g_cacheBusy=true;g_cacheStatus=L"正在清理缓存…";InvalidateRect(g_window,nullptr,FALSE);std::thread([](){auto* result=new CacheCleanResult;auto targets=CacheTargets();for(auto& entry:targets)CleanCacheEntry(entry,*result);if(!PostMessageW(g_window,WM_CACHE_CLEAN_DONE,0,(LPARAM)result))delete result;}).detach();}
