ULONGLONG DirUsage(const wstring& root,DWORD& files,size_t limit){std::error_code ec;ULONGLONG bytes=0;files=0;fs::recursive_directory_iterator it(root,fs::directory_options::skip_permission_denied,ec),end;while(it!=end){if(files>=limit)break;if(ec){ec.clear();it.increment(ec);continue;}std::error_code local;if(it->is_regular_file(local)){auto size=it->file_size(local);if(!local)bytes+=size;files++;}it.increment(ec);}return bytes;}

void CollectInstalledNames(std::vector<wstring>& out){auto read=[&](HKEY root,const wstring& base){HKEY h;if(RegOpenKeyExW(root,base.c_str(),0,KEY_READ|KEY_WOW64_64KEY,&h)!=ERROR_SUCCESS)return;for(DWORD index=0;;index++){wchar_t name[512]{};DWORD length=512;if(RegEnumKeyExW(h,index,name,&length,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;wstring display;if(!GetRegString(root,base+L"\\"+name,L"DisplayName",display)||display.empty())continue;for(auto& c:display)if(c>=L'A'&&c<=L'Z')c=(wchar_t)(c-L'A'+L'a');out.push_back(display);}RegCloseKey(h);};read(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall");read(HKEY_CURRENT_USER,L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall");read(HKEY_LOCAL_MACHINE,L"SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall");}

void StartAppScan(){if(g_appBusy)return;g_appBusy=true;g_appStatus=L"正在统计应用数据目录…";InvalidateRect(g_window,nullptr,FALSE);std::thread([](){auto* result=new AppScanResult;std::vector<wstring> installed;CollectInstalledNames(installed);const wchar_t* roots[]={L"LOCALAPPDATA",L"APPDATA"};for(auto name:roots){wstring root=EnvPath(name);if(root.empty())continue;std::error_code ec;fs::directory_iterator it(root,fs::directory_options::skip_permission_denied,ec),end;while(it!=end){if(ec){ec.clear();it.increment(ec);continue;}std::error_code local;if(it->is_directory(local)){wstring dir=it->path().wstring();wstring label=it->path().filename().wstring();if(label.size()>1&&label[0]!=L'.'){DWORD files=0;ULONGLONG bytes=DirUsage(dir,files,120000);if(bytes>4ULL*1048576ULL){AppDataItem item;item.name=label;item.path=dir;item.bytes=bytes;item.files=files;wstring lower=label;for(auto& c:lower)if(c>=L'A'&&c<=L'Z')c=(wchar_t)(c-L'A'+L'a');item.orphan=true;for(auto& n:installed)if(n.find(lower)!=wstring::npos){item.orphan=false;break;}result->items.push_back(std::move(item));}}}it.increment(ec);}}std::sort(result->items.begin(),result->items.end(),[](const AppDataItem& a,const AppDataItem& b){return a.bytes>b.bytes;});if(result->items.size()>16)result->items.resize(16);if(!PostMessageW(g_window,WM_APP_SCAN_DONE,0,(LPARAM)result))delete result;}).detach();}

