bool RegDword(HKEY root,const wstring& path,const wstring& name,DWORD& value,REGSAM view=0){HKEY h;if(RegOpenKeyExW(root,path.c_str(),0,KEY_READ|view,&h)!=ERROR_SUCCESS)return false;DWORD type=0,size=sizeof(DWORD);LONG rc=RegQueryValueExW(h,name.c_str(),nullptr,&type,(LPBYTE)&value,&size);RegCloseKey(h);return rc==ERROR_SUCCESS&&type==REG_DWORD;}

void RunRiskChecks(){g_riskItems.clear();const wstring firewall=L"SYSTEM\\CurrentControlSet\\Services\\SharedAccess\\Parameters\\FirewallPolicy";DWORD value=0;bool domainKnown=RegDword(HKEY_LOCAL_MACHINE,firewall+L"\\StandardProfile",L"EnableFirewall",value),domainOn=value!=0;bool publicKnown=RegDword(HKEY_LOCAL_MACHINE,firewall+L"\\PublicProfile",L"EnableFirewall",value),publicOn=value!=0;g_riskItems.push_back({L"Windows 防火墙",domainKnown&&publicKnown?(domainOn&&publicOn?L"域与公用网络配置均已开启":L"至少一个网络配置的防火墙处于关闭状态"):L"未能读取防火墙策略，可能被组策略接管",L"ms-settings:windowsdefender",(domainKnown&&publicKnown&&domainOn&&publicOn)?0:2});DWORD disabled=0;bool realtimeOff=(RegDword(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Policies\\Microsoft\\Windows Defender",L"DisableRealtimeMonitoring",disabled)&&disabled==1)||(RegDword(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Windows Defender\\Real-Time Protection",L"DisableRealtimeMonitoring",disabled)&&disabled==1);g_riskItems.push_back({L"杀毒实时保护",realtimeOff?L"实时保护被策略关闭，新下载的文件不会被即时扫描":L"未发现关闭实时保护的相关策略",L"ms-settings:windowsdefender",realtimeOff?2:0});DWORD deny=1;bool denyKnown=RegDword(HKEY_LOCAL_MACHINE,L"SYSTEM\\CurrentControlSet\\Control\\Terminal Server",L"fDenyTSConnections",deny);g_riskItems.push_back({L"远程桌面",!denyKnown?L"未能读取远程桌面策略":(deny?L"远程桌面已禁用，外部无法直接连接":L"远程桌面处于开启状态，请确认账户口令足够强"),L"ms-settings:remotedesktop",(!denyKnown||deny)?0:1});DWORD uac=1;bool uacKnown=RegDword(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System",L"EnableLUA",uac);DWORD consent=5;bool consentKnown=RegDword(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Policies\\System",L"ConsentPromptBehaviorAdmin",consent);g_riskItems.push_back({L"用户账户控制",!uacKnown?L"未能读取 UAC 配置":(uac==0?L"UAC 已关闭，程序可在无提示下提升权限":(consentKnown&&consent==0?L"管理员提权不弹窗，风险偏高":L"UAC 已启用，提权会弹窗确认")),L"UserAccountControlSettings.exe",(!uacKnown||uac==0||(consentKnown&&consent==0))?2:0});DWORD smb1=0;bool smb1On=RegDword(HKEY_LOCAL_MACHINE,L"SYSTEM\\CurrentControlSet\\Services\\LanmanServer\\Parameters",L"SMB1",smb1)&&smb1==1;g_riskItems.push_back({L"SMB1 协议",smb1On?L"SMB1 已启用，该协议存在已知漏洞，建议关闭":L"SMB1 未启用",L"optionalfeatures.exe",smb1On?1:0});DWORD noUpdate=0;bool updateOff=RegDword(HKEY_LOCAL_MACHINE,L"SOFTWARE\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU",L"NoAutoUpdate",noUpdate)&&noUpdate==1;g_riskItems.push_back({L"自动更新",updateOff?L"自动更新被策略关闭，补丁不会自动安装":L"未发现关闭自动更新的策略",L"ms-settings:windowsupdate",updateOff?1:0});double freeRatio=g_computerInfo.diskTotal>0?g_computerInfo.diskFree/g_computerInfo.diskTotal:1.0;g_riskItems.push_back({L"系统盘余量",FormatGb(g_computerInfo.diskFree)+L" 可用 · 占比 "+std::to_wstring((int)std::lround(freeRatio*100))+L"%",L"",freeRatio<0.1?2:(freeRatio<0.2?1:0)});RefreshStartupItems();int startupCount=(int)g_startupItems.size();g_riskItems.push_back({L"开机启动项",std::to_wstring(startupCount)+L" 项会随登录启动",L"",startupCount>14?1:0});g_riskItems.push_back({L"内存压力",std::to_wstring(g_memoryPercent)+L"% 正在使用 · 阈值 "+std::to_wstring(g_config.threshold)+L"%",L"",g_memoryPercent>=g_config.threshold?1:0});g_riskScanned=true;int risky=0;for(auto& item:g_riskItems)if(item.level>0)risky++;g_riskStatus=risky?std::to_wstring(risky)+L" 项需要关注":L"全部检查通过";InvalidateRect(g_window,nullptr,FALSE);}

