struct AssistantAdvice{wstring title,detail;int action=0;};
std::vector<AssistantAdvice> g_advice;wstring g_assistantAnswer=L"点击「生成诊断」，我会基于本机真实读数给出按优先级排好的建议。";int g_assistantTopic=0;

void BuildAssistantAnswer(int topic){std::wostringstream text;g_advice.clear();auto procs=ScanProcesses(true);std::sort(procs.begin(),procs.end(),[](const ProcessItem& a,const ProcessItem& b){return a.memory>b.memory;});std::wostringstream top;int shown=0;for(auto& item:procs){if(shown>=3)break;if(item.memory<80ULL*1024*1024)break;top<<(shown?L" · ":L"")<<item.name<<L" "<<(item.memory/1048576)<<L" MB";shown++;}if(topic==0){text<<L"本机当前内存占用 "<<g_memoryPercent<<L"%，阈值 "<<g_config.threshold<<L"%。";if(g_memoryPercent>=g_config.threshold)text<<L"已经越过阈值，建议先释放工作集。";else text<<L"仍有余量，不必急着优化。";text<<L"\n";if(shown)text<<L"内存占用最高的是 "<<top.str()<<L"。\n";if(g_cacheTotal>256ULL*1048576)text<<L"缓存可清理约 "<<FormatBytes(g_cacheTotal)<<L"。\n";if(g_computerInfo.diskTotal>0&&g_computerInfo.diskFree/g_computerInfo.diskTotal<0.2)text<<L"系统盘可用空间不足两成。\n";if(g_memoryPercent>=g_config.threshold)g_advice.push_back({L"释放内存工作集",L"对当前用户的普通进程执行 EmptyWorkingSet",1});if(g_cacheTotal>256ULL*1048576)g_advice.push_back({L"清理可重建缓存",L"临时目录、浏览器缓存与缩略图缓存",2});if(g_computerInfo.diskTotal>0&&g_computerInfo.diskFree/g_computerInfo.diskTotal<0.2)g_advice.push_back({L"查看存储分布",L"找出占用最大的目录优先清理",5});g_advice.push_back({L"跑一次风险检测",L"核对防火墙、实时保护与补丁策略",4});}else if(topic==1){text<<L"内存 "<<FormatGb(g_usedGb)<<L" / "<<FormatGb(g_totalGb)<<L" 正在使用。\n";if(shown)text<<L"占用前三："<<top.str()<<L"。\n";text<<L"优化只整理工作集，不动进程本身；如果某个进程长期占用过大，建议直接结束它。";g_advice.push_back({L"立即整理工作集",L"可访问的本用户进程逐个释放",1});g_advice.push_back({L"结束占用最高的进程",L"在系统维护的进程列表里勾选后结束",3});}else if(topic==2){ULONGLONG used=g_computerInfo.diskTotal>0?(ULONGLONG)((g_computerInfo.diskTotal-g_computerInfo.diskFree)*1073741824.0):0;text<<L"系统盘已用 "<<FormatBytes(used)<<L"，可用 "<<FormatGb(g_computerInfo.diskFree)<<L"。\n缓存可清理 "<<FormatBytes(g_cacheTotal)<<L"。\n存储页面能按目录列出真实占用，先清最大的那块收益最高。";g_advice.push_back({L"清理缓存",L"临时文件、浏览器缓存等可安全重建的数据",2});g_advice.push_back({L"打开存储空间",L"按目录查看占用并定位大户",5});g_advice.push_back({L"App 清理",L"找出应用数据目录里的疑似残留",6});}else{if(!g_riskScanned)RunRiskChecks();int risky=0;for(auto& item:g_riskItems)if(item.level>0)risky++;text<<L"共检测 "<<g_riskItems.size()<<L" 项开关，"<<(risky?std::to_wstring(risky)+L" 项需要关注":L"全部正常")<<L"。\n";for(auto& item:g_riskItems)if(item.level>0)text<<L"· "<<item.title<<L"："<<item.detail<<L"\n";g_advice.push_back({L"打开风险检测",L"逐项查看并跳转到对应系统设置",4});}g_assistantAnswer=text.str();}

