wstring Utf8ToWide(const std::string& s){if(s.empty())return L"";int n=MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0);if(n<=0)return L"";wstring out((size_t)n,L'\0');MultiByteToWideChar(CP_UTF8,0,s.data(),(int)s.size(),out.data(),n);return out;}
bool HttpGetText(const wstring& host,const wstring& target,std::string& out){HINTERNET session=WinHttpOpen(L"NovaMemory-Updater/1.0",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,WINHTTP_NO_PROXY_NAME,WINHTTP_NO_PROXY_BYPASS,0);if(!session)return false;WinHttpSetTimeouts(session,5000,5000,8000,12000);HINTERNET connect=WinHttpConnect(session,host.c_str(),INTERNET_DEFAULT_HTTPS_PORT,0);bool ok=false;if(connect){HINTERNET request=WinHttpOpenRequest(connect,L"GET",target.c_str(),nullptr,WINHTTP_NO_REFERER,WINHTTP_DEFAULT_ACCEPT_TYPES,WINHTTP_FLAG_SECURE);if(request){DWORD status=0,size=sizeof(status);if(WinHttpSendRequest(request,WINHTTP_NO_ADDITIONAL_HEADERS,0,nullptr,0,0,0)&&WinHttpReceiveResponse(request,nullptr)&&WinHttpQueryHeaders(request,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,WINHTTP_HEADER_NAME_BY_INDEX,&status,&size,WINHTTP_NO_HEADER_INDEX)&&status==200){DWORD available=0;char buffer[4096];while(WinHttpQueryDataAvailable(request,&available)&&available){DWORD read=0;DWORD want=available<(DWORD)sizeof(buffer)?available:(DWORD)sizeof(buffer);if(!WinHttpReadData(request,buffer,want,&read)||!read)break;out.append(buffer,read);if(out.size()>262144)break;}ok=true;}WinHttpCloseHandle(request);}WinHttpCloseHandle(connect);}WinHttpCloseHandle(session);return ok;}
wstring ExeVersion(const wstring& path){DWORD size=GetFileVersionInfoSizeW(path.c_str(),nullptr);if(!size)return L"";std::vector<BYTE> buffer(size);if(!GetFileVersionInfoW(path.c_str(),0,size,buffer.data()))return L"";VS_FIXEDFILEINFO* info=nullptr;UINT length=0;if(!VerQueryValueW(buffer.data(),L"\\",(void**)&info,&length)||!info)return L"";return std::to_wstring(HIWORD(info->dwFileVersionMS))+L"."+std::to_wstring(LOWORD(info->dwFileVersionMS))+L"."+std::to_wstring(HIWORD(info->dwFileVersionLS))+L"."+std::to_wstring(LOWORD(info->dwFileVersionLS));}
int CompareVersion(const wstring& a,const wstring& b){auto parse=[](const wstring& s){std::vector<int> parts;size_t i=0;while(i<s.size()&&!iswdigit(s[i]))i++;while(i<s.size()){int value=0;bool any=false;while(i<s.size()&&iswdigit(s[i])){value=value*10+(s[i]-L'0');any=true;i++;}if(any)parts.push_back(value);if(i>=s.size()||s[i]!=L'.')break;i++;}while(parts.size()<4)parts.push_back(0);return parts;};std::vector<int> x=parse(a),y=parse(b);for(size_t i=0;i<4;i++){if(x[i]!=y[i])return x[i]<y[i]?-1:1;}return 0;}
wstring CurrentExePath(){std::array<wchar_t,32768> exe{};DWORD length=GetModuleFileNameW(nullptr,exe.data(),(DWORD)exe.size());if(!length||length>=exe.size())return L"";return wstring(exe.data(),length);}
std::vector<wstring> ShortcutExeCandidates(){std::vector<wstring> found;wstring current=CurrentExePath();if(!current.empty())found.push_back(current);auto addDir=[&](const wstring& dir){if(dir.empty())return;std::error_code ec;for(fs::directory_iterator it(dir,ec),end;!ec&&it!=end;it.increment(ec)){if(!it->is_regular_file(ec))continue;wstring name=it->path().filename().wstring();if(name.size()<=4)continue;wstring lower=name;std::transform(lower.begin(),lower.end(),lower.begin(),::towlower);if(lower.size()<4)continue;if(lower.compare(lower.size()-4,4,L".exe")!=0)continue;if(lower.find(L"novamemory")==wstring::npos)continue;found.push_back(it->path().wstring());}};wstring dir=AppDirectory();addDir(dir);addDir(dir+L"\\outputs");addDir(EnvPath(L"LOCALAPPDATA")+L"\\Programs\\NovaMemory");addDir(EnvPath(L"ProgramFiles")+L"\\NovaMemory");return found;}
wstring ShortcutLinkPath(){PWSTR programs=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_Programs,KF_FLAG_CREATE,nullptr,&programs)))return L"";wstring link=wstring(programs)+L"\\NovaMemory\\NovaMemory.lnk";CoTaskMemFree(programs);return link;}
bool BestExeForShortcut(wstring& bestPath,wstring& bestVersion){bestPath.clear();bestVersion.clear();for(auto& candidate:ShortcutExeCandidates()){wstring version=ExeVersion(candidate);if(version.empty())continue;if(bestVersion.empty()||CompareVersion(version,bestVersion)>0){bestVersion=version;bestPath=candidate;}}return !bestPath.empty();}
void ReportRegisterError(const wstring& message){g_config.registerError=message;SaveConfig();ShowBanner(message);g_lastAction=message;}
bool RegisterShortcut(){wstring link=ShortcutLinkPath();if(link.empty()){ReportRegisterError(L"注册失败 · 无法访问开始菜单目录");return false;}std::error_code ec;fs::create_directories(fs::path(link).parent_path(),ec);wstring best,version;if(!BestExeForShortcut(best,version)){ReportRegisterError(L"注册失败 · 找不到可注册的程序文件");return false;}if(!SaveShortcut(link,best)){ReportRegisterError(L"注册失败 · 开始菜单快捷方式写入被拒绝");return false;}g_config.registerError.clear();SaveConfig();wstring current=ExeVersion(CurrentExePath());if(!current.empty()&&CompareVersion(version,current)>0){g_lastAction=L"已注册更高版本 "+version;ShowBanner(L"已注册更高版本 v"+version+L"（本机 v"+current+L"）");}else{g_lastAction=L"已注册到系统";ShowToast(L"已注册 · 可在开始菜单搜索 NovaMemory");}return true;}
void UnregisterShortcut(){wstring link=ShortcutLinkPath();if(link.empty()){ReportRegisterError(L"取消注册失败 · 无法访问开始菜单目录");return;}wstring best,version;wstring current=ExeVersion(CurrentExePath());BestExeForShortcut(best,version);if(!version.empty()&&!current.empty()&&CompareVersion(version,current)>0){std::error_code ec;fs::create_directories(fs::path(link).parent_path(),ec);if(SaveShortcut(link,best)){g_lastAction=L"已切换为高版本 v"+version;ShowBanner(L"发现更高版本 v"+version+L" · 已改为注册该版本");return;}ReportRegisterError(L"取消注册失败 · 高版本自动注册未成功");return;}bool removed=DeleteFileW(link.c_str())!=FALSE;if(!removed&&GetLastError()!=ERROR_FILE_NOT_FOUND){ReportRegisterError(L"取消注册失败 · 快捷方式被占用");return;}g_lastAction=L"已取消注册";ShowToast(removed?L"已取消注册 · 开始菜单不再显示 NovaMemory":L"当前没有注册项");}
void StartUpdateCheck(){if(g_updateBusy)return;g_updateBusy=true;g_updateStatus=L"正在检查更新…";InvalidateRect(g_window,nullptr,FALSE);std::thread([](){auto* result=new UpdateCheckResult;std::string body;if(!HttpGetText(L"api.github.com",L"/repos/Ethan1999991231/Nova-Memory/releases/latest",body)){result->message=L"无法访问 GitHub · 请检查网络或代理";}else{wstring wide=Utf8ToWide(body);size_t tag=wide.find(L"\"tag_name\"");if(tag!=wstring::npos){size_t first=wide.find(L'"',wide.find(L':',tag));size_t second=first==wstring::npos?wstring::npos:wide.find(L'"',first+1);if(first!=wstring::npos&&second!=wstring::npos)result->version=wide.substr(first+1,second-first-1);}size_t url=wide.find(L"\"html_url\"");if(url!=wstring::npos){size_t first=wide.find(L'"',wide.find(L':',url));size_t second=first==wstring::npos?wstring::npos:wide.find(L'"',first+1);if(first!=wstring::npos&&second!=wstring::npos)result->url=wide.substr(first+1,second-first-1);}if(result->version.empty()){result->message=L"未能从 GitHub 解析版本号";}else{result->ok=true;result->newer=CompareVersion(result->version,ExeVersion(CurrentExePath()))>0;result->message=result->newer?(L"发现新版本 "+result->version):(L"已是最新版本 "+result->version);}}if(!PostMessageW(g_window,WM_UPDATE_DONE,0,(LPARAM)result))delete result;}).detach();}
