void AddToStartMenu(){std::array<wchar_t,32768> exe{};DWORD length=GetModuleFileNameW(nullptr,exe.data(),(DWORD)exe.size());if(!length||length>=exe.size()){ShowToast(L"无法读取程序路径",true);return;}PWSTR programs=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_Programs,KF_FLAG_CREATE,nullptr,&programs))){ShowToast(L"无法访问当前用户开始菜单目录",true);return;}wstring folder=programs+wstring(L"\\NovaMemory");CoTaskMemFree(programs);if(!CreateDirectoryW(folder.c_str(),nullptr)&&GetLastError()!=ERROR_ALREADY_EXISTS){ShowToast(L"无法创建开始菜单目录",true);return;}wstring link=folder+L"\\NovaMemory.lnk";if(!SaveShortcut(link,exe.data())){ShowToast(L"创建开始菜单快捷方式失败",true);return;}g_lastAction=L"已添加到开始菜单";ShowToast(L"已添加 · 可在开始菜单搜索 NovaMemory");}
void SaveDraft(){g_config.automatic=g_autoDraft;g_config.threshold=g_thresholdDraft;g_config.aggressive=g_modeDraft;g_config.allProcesses=g_allDraft;g_config.fullStartup=g_startDraft;g_config.theme=g_themeDraft;g_config.opacity=g_opacityDraft;g_config.accent=g_accentDraft;ApplyAppearance(g_config.theme,g_config.opacity,g_config.accent);if(!SaveConfig()){g_lastAction=L"设置保存失败";ShowToast(L"保存失败 · 请检查配置目录权限",true);}else{g_lastAction=L"偏好设置已保存";RefreshProcesses();RefreshStartupItems();ShowToast(L"设置已保存 · 下次启动会自动恢复");}InvalidateRect(g_window,nullptr,FALSE);}
void EndSelectedProcesses(){if(g_selectedProcesses.empty()){g_processStatus=L"先点选一个进程，再按“结束选中”";ShowToast(g_processStatus,true);return;}wstring names;int shown=0;for(const auto& item:g_processes)if(g_selectedProcesses.count(item.pid)&&shown++<5)names+=item.name+L"\n";g_pendingProcessIds=g_selectedProcesses;wstring prompt=L"将结束 "+std::to_wstring(g_selectedProcesses.size())+L" 个进程：\n\n"+names+L"未保存的数据可能丢失。";ShowPrompt(PromptKind::EndProcesses,L"确认结束进程",prompt);}
void ExecuteEndSelectedProcesses(){std::set<DWORD> ids=g_pendingProcessIds;DismissPrompt();std::vector<HANDLE> pending;int failed=0;for(DWORD pid:ids){auto item=std::find_if(g_processes.begin(),g_processes.end(),[pid](const ProcessItem& candidate){return candidate.pid==pid;});if(item==g_processes.end()||pid<=4||IsCritical(item->name)){failed++;continue;}HANDLE process=OpenProcess(PROCESS_TERMINATE|PROCESS_QUERY_LIMITED_INFORMATION|SYNCHRONIZE,FALSE,pid);if(!process){failed++;continue;}wchar_t image[32768]={};DWORD length=32768;bool same=QueryFullProcessImageNameW(process,0,image,&length)!=FALSE;if(same){wstring actual=image;size_t slash=actual.find_last_of(L"\\/");if(slash!=wstring::npos)actual.erase(0,slash+1);same=!_wcsicmp(actual.c_str(),item->name.c_str());}if(!same){CloseHandle(process);failed++;continue;}if(TerminateProcess(process,1)||WaitForSingleObject(process,0)==WAIT_OBJECT_0)pending.push_back(process);else{CloseHandle(process);failed++;}}g_selectedProcesses.clear();if(pending.empty()){RefreshProcesses();g_processStatus=L"结束失败：没有进程成功退出，请检查权限后重试";g_lastAction=g_processStatus;ShowToast(g_processStatus,true);return;}g_processStatus=L"正在等待 "+std::to_wstring(pending.size())+L" 个进程退出…";g_lastAction=g_processStatus;ShowToast(g_processStatus);std::thread([handles=std::move(pending),failed]()mutable{ULONGLONG deadline=GetTickCount64()+5000;ProcessStopResult* result=new ProcessStopResult;result->failed=failed;for(HANDLE process:handles){ULONGLONG now=GetTickCount64();DWORD remaining=now>=deadline?0:(DWORD)(deadline-now);if(WaitForSingleObject(process,remaining)==WAIT_OBJECT_0)result->stopped++;else result->failed++;CloseHandle(process);}if(!PostMessageW(g_window,WM_PROCESS_STOP_DONE,0,(LPARAM)result))delete result;}).detach();}
void ConfirmPrompt(){if(g_promptKind==PromptKind::RegistryCleanup)ConfirmRegistryCleanup();else if(g_promptKind==PromptKind::EndProcesses)ExecuteEndSelectedProcesses();else if(g_promptKind==PromptKind::CacheCleanup){DismissPrompt();StartCacheClean();}}
void ToggleStartupItem(){if(g_selectedStartup<0||g_selectedStartup>=(int)g_startupItems.size())return;auto item=g_startupItems[g_selectedStartup];bool next=!item.enabled;if(!SetStartupEnabled(item,next)){ShowToast(L"无法更改该启动项 · 可能需要管理员权限",true);return;}RefreshStartupItems();g_lastAction=next?L"启动项已重新启用":L"启动项已禁用";ShowToast(g_lastAction);InvalidateRect(g_window,nullptr,FALSE);}

