case WM_CREATE:g_window=h;ApplyAppearance(g_config.theme,g_config.opacity,g_config.accent);SetTimer(h,1,250,nullptr);RefreshMemory();SendMessageW(h,WM_SETICON,ICON_BIG,(LPARAM)LoadImageW(GetModuleHandleW(nullptr),MAKEINTRESOURCEW(IDI_NOVAMEMORY),IMAGE_ICON,32,32,LR_DEFAULTCOLOR));SendMessageW(h,WM_SETICON,ICON_SMALL,(LPARAM)LoadImageW(GetModuleHandleW(nullptr),MAKEINTRESOURCEW(IDI_NOVAMEMORY),IMAGE_ICON,16,16,LR_DEFAULTCOLOR));SampleCpu();AddTrayIcon();if(!g_config.registerError.empty()){ShowBanner(g_config.registerError);g_config.registerError.clear();SaveConfig();}return 0;
case WM_ERASEBKGND:return 1;
case WM_PAINT:Paint(h);return 0;
case WM_OPTIMIZE_DONE:{std::unique_ptr<OptimizeResult> r((OptimizeResult*)l);g_memoryPercent=r->after;MEMORYSTATUSEX m{sizeof(m)};if(GlobalMemoryStatusEx(&m)){g_totalGb=m.ullTotalPhys/1073741824.0;g_usedGb=(m.ullTotalPhys-m.ullAvailPhys)/1073741824.0;}std::wostringstream s;s<<L"已完成 · 整理 "<<r->processed<<L" 个进程";if(r->after<r->before)s<<L" · 负载下降 "<<(r->before-r->after)<<L"%";g_lastAction=s.str();if(r->automatic)g_lastAuto=std::time(nullptr);g_optimizing=false;InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_PROCESS_STOP_DONE:{std::unique_ptr<ProcessStopResult> result((ProcessStopResult*)l);RefreshProcesses();g_processStatus=L"已退出 "+std::to_wstring(result->stopped)+L" 个进程";if(result->failed)g_processStatus+=L"；"+std::to_wstring(result->failed)+L" 个失败（可能缺少权限）";g_lastAction=g_processStatus;ShowToast(g_processStatus,result->failed>0);InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_PROCESS_REFRESH_DONE:{std::unique_ptr<ProcessRefreshResult> result((ProcessRefreshResult*)l);if(result->generation!=g_processRefreshGeneration)return 0;g_processes=std::move(result->items);g_processLoading=false;g_selectedProcesses.clear();g_scroll=0;if(g_processStatus==L"正在刷新进程列表…")g_processStatus=L"已找到 "+std::to_wstring(g_processes.size())+L" 个可管理进程";InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_CACHE_SCAN_DONE:{std::unique_ptr<CacheScanResult> result((CacheScanResult*)l);g_cacheEntries=std::move(result->entries);g_cacheTotal=0;for(auto& entry:g_cacheEntries)if(!entry.recycleBin)g_cacheTotal+=entry.bytes;g_cacheBusy=false;g_cacheLastScan=GetTickCount64();std::wostringstream status;status<<L"共 "<<FormatBytes(g_cacheTotal)<<L" 可清理";if(g_cacheTotal==0)status<<L" · 已经很干净";g_cacheStatus=status.str();InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_CACHE_CLEAN_DONE:{std::unique_ptr<CacheCleanResult> result((CacheCleanResult*)l);std::wostringstream summary;summary<<L"已清理 "<<FormatBytes(result->freed)<<L" · 删除 "<<result->removed<<L" 个文件";if(result->skipped)summary<<L" · "<<result->skipped<<L" 个被占用跳过";g_cacheStatus=summary.str();g_lastAction=summary.str();ShowToast(summary.str(),result->removed==0);g_cacheBusy=false;StartCacheScan();return 0;}
case WM_REGISTRY_SCAN_DONE:{std::unique_ptr<RegistryScanResult> result((RegistryScanResult*)l);g_registryItems=std::move(result->items);g_registryBusy=false;g_registryScanned=true;std::wostringstream status;if(g_registryItems.empty())status<<L"体检完成 · 未发现失效记录";else status<<L"体检完成 · 发现 "<<g_registryItems.size()<<L" 项失效记录";g_registryStatus=status.str();InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_APP_SCAN_DONE:{std::unique_ptr<AppScanResult> result((AppScanResult*)l);g_appItems=std::move(result->items);g_appBusy=false;g_appScanned=true;g_appSelected=-1;ULONGLONG total=0;int orphans=0;for(auto& item:g_appItems){total+=item.bytes;if(item.orphan)orphans++;}std::wostringstream status;status<<L"共 "<<FormatBytes(total)<<L" · "<<g_appItems.size()<<L" 个目录";if(orphans)status<<L" · "<<orphans<<L" 个疑似残留";g_appStatus=status.str();InvalidateRect(h,nullptr,FALSE);return 0;}
case WM_STORAGE_SCAN_DONE:{std::unique_ptr<StorageScanResult> result((StorageScanResult*)l);g_storageItems=std::move(result->items);g_drives=std::move(result->drives);g_storageTotal=result->total;g_storageFree=result->free;g_storageBusy=false;g_storageScanned=true;std::wostringstream status;status<<L"系统盘已用 "<<FormatBytes(g_storageTotal-g_storageFree)<<L" · 可用 "<<FormatBytes(g_storageFree);g_storageStatus=status.str();InvalidateRect(h,nullptr,FALSE);return 0;}
