case WM_TIMER:if(w==1){RefreshMemory();UpdateTrayTip();if(g_config.automatic&&g_memoryPercent>=g_config.threshold&&std::time(nullptr)-g_lastAuto>=60)OptimizeMemory(true);}else if(w==2){if(GetTickCount64()-g_pageTransitionStarted>=180){g_pageTransition=false;KillTimer(h,2);}InvalidateRect(h,nullptr,FALSE);}else if(w==3){if(!UpdateButtonMotions(GetTickCount64()))KillTimer(h,3);InvalidateRect(h,nullptr,FALSE);}else if(w==4){if(GetTickCount64()-g_toastStarted>=2600){g_toastText.clear();KillTimer(h,4);}InvalidateRect(h,nullptr,FALSE);}else if(w==5){if(GetTickCount64()-g_toggleStarted>=1000){g_toggleValue=g_toggleTo;KillTimer(h,5);}InvalidateRect(h,nullptr,FALSE);}else if(w==6){RefreshComputerUsage();SampleCpu();InvalidateRect(h,nullptr,FALSE);}else if(w==7){if(GetTickCount64()-g_bannerStarted>=BANNER_MS){g_bannerText.clear();KillTimer(h,7);}InvalidateRect(h,nullptr,FALSE);}return 0;
